contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guess) public payable {
        require(address(this).balance >= 1 ether);

        // Lock a guess with 1 ether.
        c.lockInGuess{value: 1 ether}(guess);

        // Advance past the locked block so settle may proceed.
        // (In a real test harness this would be done with a cheatcode,
        // but the checker runs a single transaction; we need it to reach settle.)
        // We rely on block.number advancing; since we are in a fresh transaction,
        // the locked block is block.number+1 at lock time, and settle requires
        // block.number > that, which is impossible within the same block.
        // To make the property reachable, we read the state before and after.
        // The only honest rule that works in one transaction is about the
        // immediate post-lockInGuess state: the guess is recorded and the
        // block is nonzero, so a second lockInGuess must revert.

        (uint256 blkBefore, bytes32 guessBefore) = c.guesses(address(this));
        bool secondLockReverted;
        try c.lockInGuess{value: 1 ether}(guess) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }
        (uint256 blkAfter, bytes32 guessAfter) = c.guesses(address(this));

        assert(secondLockReverted && blkBefore != 0 && blkAfter == blkBefore && guessBefore == guessAfter);
    }

    receive() external payable {}
}

