contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash, uint lockAmount) public payable {
        require(address(this).balance >= lockAmount, "balance must cover lockAmount");

        // lockInGuess requires exactly 1 ether, so either the call reverts
        // or it must have been supplied exactly 1 ether.
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // If lockInGuess succeeded, settle must be callable and any payout must
        // follow the rule: exact match pays exactly 2 ether, otherwise 0.
        bool settleReverted;
        uint balanceBefore = address(this).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint received = address(this).balance - balanceBefore;

        assert(
            lockReverted
                ? (settleReverted || received == 0)
                : (settleReverted || received == 0 || received == 2 ether)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash) public payable {
        require(address(this).balance >= 1 ether, "need 1 ether");

        // lock the guess: can revert, catch it
        bool lockReverted;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // read the locked guess through public getter
        bytes32 storedGuess = c.guesses(address(this)).guess;

        // settle: can revert (e.g. same block)
        bool settleReverted;
        uint balanceBefore = address(this).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // after a successful settle, block field is cleared
        uint storedBlock = c.guesses(address(this)).block;

        uint received = address(this).balance - balanceBefore;

        // General rule: if lock succeeded and settle succeeded, then
        // the caller receives exactly 2 ether iff the stored guess equals the
        // blockhash of the target block (which is unknown, but observable only
        // via payout). We express the guarantee structurally:
        //   - success payout can only be 0 or 2 ether,
        //   - if the guess was set (lock succeeded) and settle succeeded, block is cleared.
        assert(
            lockReverted
                ? true
                : (settleReverted
                    ? storedGuess == guessHash && storedBlock != 0
                    : (storedBlock == 0 && (received == 0 || received == 2 ether)))
        );
    }

    receive() external payable {}
}

